import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';

const root = resolve(import.meta.dirname, '..');
const files = [
  ['kIndexHtml', 'site/index.html'],
  ['kStylesCss', 'site/styles.css'],
  ['kAppJs', 'site/app.js'],
];

function cppString(value) {
  return JSON.stringify(value).replace(/\\u2028/g, '\\u2028').replace(/\\u2029/g, '\\u2029');
}

const chunks = [
  '// Generated by scripts/generate-site-header.mjs. Do not edit by hand.',
  '#pragma once',
  '#include <pgmspace.h>',
  '',
];

for (const [name, relativePath] of files) {
  const content = await readFile(resolve(root, relativePath), 'utf8');
  chunks.push(`const char ${name}[] PROGMEM = ${cppString(content)};`);
}

const output = resolve(root, 'firmware/esp32d_static_site/site_html.h');
await mkdir(dirname(output), { recursive: true });
await writeFile(output, `${chunks.join('\n')}\n`);
console.log(`Generated ${output}`);
